import SwiftUI

struct InformationView:View {
    @EnvironmentObject var store:DeskStore
    @SwiftUI.State private var title=""
    @SwiftUI.State private var target=Date()
    private let choices=[("nextEvent","下一场日程"),("outdoor","出门天气"),("countdown","重要日倒计时"),("week","本周进度"),("note","桌面小纸条"),("plant","生长小盆栽"),("status","办公状态"),("habits","习惯打卡"),("inspiration","每日灵感"),("commute","通勤建议"),("plugin","数据插件")]
    var body:some View {
        SectionIntro(eyebrow:"A LITTLE MORE USEFUL",title:"有用的信息，刚刚好。",subtitle:"待办仍是主角。为右侧选两张卡，让每一眼都有收获。")
        Card{VStack(alignment:.leading,spacing:14){Text("桌面场景").font(.system(size:18,weight:.semibold));Text("点击场景会明确全刷一次，保留当前待办。不同客户端的完成历史分别统计。").font(.system(size:11)).foregroundStyle(muted);HStack{Button("工作桌面 · 全刷"){applyScene("work")}.buttonStyle(Quiet());Button("专注桌面 · 全刷"){applyScene("focus")}.buttonStyle(Quiet());Button("生活画报 · 全刷"){applyScene("life")}.buttonStyle(Quiet())}.disabled(store.isSending);HStack{Picker("办公状态",selection:Binding(get:{store.settings.info.deskStatus ?? "专注中"},set:{value in store.configureInformation{$0.deskStatus=value}})){ForEach(["专注中","开会中","暂时离开","今日已下班"],id:\.self){Text($0)}};TextField("状态补充（最多30字）",text:Binding(get:{store.settings.info.statusNote ?? "请稍后联系"},set:{value in store.configureInformation{$0.statusNote=String(value.prefix(30))}})).textFieldStyle(.roundedBorder)}}}
        HStack(alignment:.top,spacing:22){
            VStack(spacing:22){
                Card{VStack(alignment:.leading,spacing:18){Label("屏幕信息卡",systemImage:"rectangle.grid.1x2").font(.system(size:18,weight:.semibold));ForEach(0..<2,id:\.self){slot in Picker(slot==0 ? "上方卡片":"下方卡片",selection:cardBinding(slot)){ForEach(choices,id:\.0){Text($0.1).tag($0.0)}}};Text("用于专注办公、今日安排、信息总览布局；其他布局保留各自特色。卡片内容变化走黑白局刷。").font(.system(size:11)).foregroundStyle(muted);ScreenPreview(content:store.content)}}
                Card{VStack(alignment:.leading,spacing:16){Label("重要的日子",systemImage:"calendar.badge.clock").font(.system(size:18,weight:.semibold));TextField("例如：项目交付、生日、旅行",text:$title).textFieldStyle(.roundedBorder);HStack{DatePicker("目标日期",selection:$target,displayedComponents:.date);Button("添加"){addDate()}.buttonStyle(Quiet()).disabled(title.trimmingCharacters(in:.whitespacesAndNewlines).isEmpty||store.settings.info.dates.count>=12)};Text("最多12个日期，卡片优先显示最近的未来日期；目前按自然日计算。").font(.system(size:11)).foregroundStyle(muted);ForEach(store.settings.info.dates.sorted{$0.date<$1.date}){item in HStack{VStack(alignment:.leading){Text(item.title);Text(InformationLogic.countdown(item,at:store.now).replacingOccurrences(of:"\n",with:" · ")).foregroundStyle(muted)};Spacer();Button("移除"){store.configureInformation{$0.dates.removeAll{$0.id==item.id}}}.buttonStyle(.plain)}.font(.system(size:12))}}}
            }
            VStack(spacing:22){
                Card{VStack(alignment:.leading,spacing:16){Label("本周小目标",systemImage:"chart.bar").font(.system(size:17,weight:.semibold));Text("已完成 \(InformationLogic.weekCount(store.tasks,store.settings.info,at:store.now)) 项").font(.system(size:24,weight:.medium));Stepper("每周目标 \(store.settings.info.weeklyGoal) 项",value:Binding(get:{store.settings.info.weeklyGoal},set:{v in store.configureInformation{$0.weeklyGoal=v}}),in:1...100);Text("周一至周日，按实际完成时间统计。撤销完成后同步扣除。").font(.system(size:11)).foregroundStyle(muted)}}
                Card{VStack(alignment:.leading,spacing:16){Label("下一场日程",systemImage:"calendar").font(.system(size:17,weight:.semibold));Toggle("显示系统日历",isOn:Binding(get:{store.settings.info.calendarEnabled},set:{v in store.configureInformation{$0.calendarEnabled=v}}));Button(store.calendarBusy ? "等待系统授权…":"授权读取系统日历"){Task{await store.authorizeCalendar()}}.buttonStyle(Quiet()).disabled(store.calendarBusy);Text(store.calendarStatus).font(.system(size:11)).foregroundStyle(muted);ForEach(store.calendarChoices,id:\.id){calendar in Toggle(calendar.title,isOn:Binding(get:{store.settings.info.calendarIDs.contains(calendar.id)},set:{selected in store.configureInformation{info in if selected{info.calendarIDs.append(calendar.id)}else{info.calendarIDs.removeAll{$0==calendar.id}}}})).font(.system(size:12))};if let event=store.nextEvent{Text(event.summary(at:store.now)).font(.system(size:13))};Text("只展示你选择的日历。日程在本机读取并同步至你的墨水屏，不自动发送给 DeepSeek。").font(.system(size:11)).foregroundStyle(muted)}}
                Card{VStack(alignment:.leading,spacing:16){Label("出门天气",systemImage:"cloud.sun").font(.system(size:17,weight:.semibold));Text(InformationLogic.outdoor(store.weather,at:store.now)).font(.system(size:14));Text("逐小时预报，不代表精确的降雨起止时间。").font(.system(size:11)).foregroundStyle(muted);Button(store.feedBusy ? "正在更新…":"更新天气"){Task{await store.refreshFeeds(forceWeather:true);store.changed()}}.buttonStyle(Quiet()).disabled(store.feedBusy)}}
            }.frame(width:340)
        }
        .onAppear{store.refreshCalendar()}
    }
    private func applyScene(_ scene:String){Task{await store.applyScene(scene)}}
    private func cardBinding(_ slot:Int)->Binding<String> {Binding(get:{let cards=store.settings.info.cards;return slot<cards.count ? cards[slot]:(slot==0 ? "nextEvent":"outdoor")},set:{key in store.configureInformation{info in var cards=info.cards;if cards.count != 2{cards=["nextEvent","outdoor"]};let other=1-slot;if cards[other]==key{cards[other]=cards[slot]};cards[slot]=key;info.cards=cards}})}
    private func addDate(){let name=title.trimmingCharacters(in:.whitespacesAndNewlines);guard !name.isEmpty,name.count<=30,store.settings.info.dates.count<12 else{store.status="日期名称请填写1至30个字";return};store.configureInformation{$0.dates.append(ImportantDate(title:name,date:WorkSchedule.calendar.startOfDay(for:target)))};title=""}
}
